  async function removeLoan(loan){if(loanDeletingId!==null)return;loanDeletingId=loan.id;loanError='';try{await deleteLoan(loan.id);loans=loans.filter(item=>item.id!==loan.id);saveMoneyModulesCache();await refreshStories();}catch(cause){loanError=cause?.message||'Could not delete this loan.';}finally{loanDeletingId=null;}}
  async function payLoanEmi(loan, occurrence){try{await markLoanEmiPaid(loan.id,occurrence.month);await Promise.all([loadLoans(),refreshStories()]);}catch(cause){loanError=cause?.message||'Could not mark this EMI paid.';}}
  function openMutualFundForm(){fundError='';fundSaved=false;schemeQuery='';selectedScheme=null;showSchemeMenu=false;fundForm={hasSip:'YES',sipAmount:'25000',sipDate:'5',startMonth:'2026-10',hasHolding:'YES',currentUnits:'128.456',totalInvested:'10000'};showMutualFundForm=true;}
  async function searchSchemes(value){schemeQuery=value;selectedScheme=null;showSchemeMenu=true;fundError='';if(value.trim().length<2){schemeResults=[];schemeSearchStatus='idle';return;}const requestId=++schemeSearchRequest;schemeSearchStatus='loading';try{const result=await searchMutualFunds(value.trim());if(requestId!==schemeSearchRequest)return;schemeResults=Array.isArray(result)?result:result.schemes||[];schemeSearchStatus='ready';}catch(cause){if(requestId!==schemeSearchRequest)return;schemeResults=[];schemeSearchStatus='error';fundError=cause?.message||'Could not search the scheme master.';}}
  function selectScheme(scheme){selectedScheme=scheme;schemeQuery=scheme.schemeName;showSchemeMenu=false;fundError='';}
  async function saveMutualFund(){const sipAmount=Number(fundForm.sipAmount),units=Number(fundForm.currentUnits),invested=Number(fundForm.totalInvested);if(!selectedScheme){fundError='Choose a scheme from the verified scheme master.';return;}if(fundForm.hasSip==='YES'&&(sipAmount<=0||!fundForm.sipDate||!fundForm.startMonth)){fundError='Add a valid monthly amount, SIP date, and start month.';return;}if(fundForm.hasHolding==='YES'&&(!(units>0)||!(invested>0))){fundError='Enter current units and invested amount greater than zero.';return;}const payload={schemeCode:selectedScheme.schemeCode,schemeName:selectedScheme.schemeName,...(fundForm.hasSip==='YES'?{monthlySipAmount:sipAmount,sipDay:Number(fundForm.sipDate),startMonth:fundForm.startMonth}:{}),...(selectedScheme.isin?{isin:selectedScheme.isin}:{}),...(fundForm.hasHolding==='YES'?{existingHolding:{currentUnits:units,totalInvestedAmount:invested}}:{})};fundSaving=true;fundError='';try{await createMutualFund(payload);fundSaved=true;await loadMutualFunds();await refreshStories();}catch(cause){fundError=cause?.message||'Could not create this mutual fund.';}finally{fundSaving=false;}}
  async function removeMutualFund(fund){if(mutualFundDeletingId!==null)return;mutualFundDeletingId=fund.id;mutualFundError='';try{await deleteMutualFund(fund.id);mutualFunds=mutualFunds.filter(item=>item.id!==fund.id);saveMoneyModulesCache();await refreshStories();}catch(cause){mutualFundError=cause?.message||'Could not delete this mutual fund.';}finally{mutualFundDeletingId=null;}}
  function openFundSipPlan(fund){fundSipTarget=fund;fundSipForm={amount:'',day:'',startMonth:new Date().toISOString().slice(0,7)};fundError='';}
  async function saveFundSipPlan(){const amount=Number(fundSipForm.amount),day=Number(fundSipForm.day);if(!(amount>0)||!(day>=1&&day<=28)||!fundSipForm.startMonth){fundError='Enter a positive monthly amount, a day from 1 to 28, and a start month.';return;}fundSipSaving=true;try{await createMutualFundSip(fundSipTarget.id,{amount,day,startMonth:fundSipForm.startMonth});fundSipTarget=null;await loadMutualFunds();await refreshStories();}catch(cause){fundError=cause?.message||'Could not save this SIP.';}finally{fundSipSaving=false;}}
  function openStockForm(){stockError='';stockQuery='';selectedStock=null;stockResults=[];stockForm={quantity:'',totalInvested:''};showStockForm=true;}
  async function findStocks(value){stockQuery=value;selectedStock=null;stockError='';if(value.trim().length<2){stockResults=[];stockSearchStatus='idle';return;}const requestId=++stockSearchRequest;stockSearchStatus='loading';try{const result=await searchStocks(value.trim());if(requestId!==stockSearchRequest)return;stockResults=Array.isArray(result)?result:[];stockSearchStatus='ready';}catch(cause){if(requestId!==stockSearchRequest)return;stockResults=[];stockSearchStatus='error';stockError=cause?.message||'Could not search stock symbols.';}}
  function selectStock(stock){selectedStock=stock;stockQuery=`${stock.name} (${stock.symbol})`;stockResults=[];stockError='';}
  async function saveStock(){const quantity=Number(stockForm.quantity),totalInvestedAmount=Number(stockForm.totalInvested);if(!selectedStock){stockError='Choose a stock from the search results.';return;}if(!(quantity>0)||!(totalInvestedAmount>0)){stockError='Enter valid positive quantity and total invested amount.';return;}stockSaving=true;stockError='';try{await createStock({symbol:selectedStock.symbol,name:selectedStock.name,exchange:selectedStock.exchange,quantity,totalInvestedAmount});showStockForm=false;await loadStocks();}catch(cause){stockError=cause?.message||'Could not add this stock.';}finally{stockSaving=false;}}
  async function removeStock(stock){if(stockDeletingId!==null)return;stockDeletingId=stock.id;stockError='';try{await deleteStock(stock.id);stocks=stocks.filter(item=>item.id!==stock.id);saveMoneyModulesCache();}catch(cause){stockError=cause?.message||'Could not delete this stock.';}finally{stockDeletingId=null;}}
  function openStockPlan(stock){stockPlanTarget=stock;stockPlanForm={amount:stock.activeMonthlyPlan?.amount||'',day:stock.activeMonthlyPlan?.day||'',startMonth:stock.activeMonthlyPlan?.startMonth||new Date().toISOString().slice(0,7)};stockError='';}
  async function saveStockPlan(){const amount=Number(stockPlanForm.amount),day=Number(stockPlanForm.day);if(!(amount>0)||!(day>=1&&day<=28)||!stockPlanForm.startMonth){stockError='Enter a positive amount, a day from 1 to 28, and a start month.';return;}stockPlanSaving=true;try{await createStockMonthlyPlan(stockPlanTarget.id,{amount,day,startMonth:stockPlanForm.startMonth});stockPlanTarget=null;await loadStocks();await refreshStories();}catch(cause){stockError=cause?.message||'Could not save this monthly plan.';}finally{stockPlanSaving=false;}}
  async function confirmStockPlan(){const amount=Number(stockPlanConfirmation.amount),executionPrice=Number(stockPlanConfirmation.price);if(!(amount>0)||!(executionPrice>0))return;try{await confirmStockMonthlyPlan(stockPlanConfirmationTarget.id,stockPlanConfirmationTarget.currentMonthlyPlan.month,{amount,executionPrice,transactionDate:new Date().toISOString().slice(0,10)});stockPlanConfirmationTarget=null;await loadStocks();await refreshStories();}catch(cause){stockError=cause?.message||'Could not confirm this ETF investment.';}}
  async function openStockDetail(id){stockDetail={id};stockDetailStatus='loading';try{stockDetail=await getStock(id);stockDetailStatus='ready';}catch(cause){stockDetailStatus='error';stockError=cause?.message||'Could not load this stock.';}}
  function openSipConfirmation(fund,occurrence){confirmingSip={fund,occurrence};sipConfirmError='';sipConfirmForm={amount:String(occurrence.amount||fund.monthlySipAmount||''),transactionDate:occurrence.transactionDate||new Date().toISOString().slice(0,10),nav:occurrence.nav==null?'':String(occurrence.nav)};}
  async function saveSipConfirmation(){const amount=Number(sipConfirmForm.amount),nav=Number(sipConfirmForm.nav);if(!(amount>0)||!sipConfirmForm.transactionDate||!(nav>0)){sipConfirmError='Enter a valid amount, transaction date, and NAV.';return;}sipConfirmSaving=true;sipConfirmError='';try{const payload={amount,transactionDate:sipConfirmForm.transactionDate,nav,calculationSource:'NAV_ESTIMATED'};if(confirmingSip.occurrence.status==='CONFIRMED')await updateSipOccurrence(confirmingSip.fund.id,confirmingSip.occurrence.scheduledMonth,payload);else await confirmSipOccurrence(confirmingSip.fund.id,confirmingSip.occurrence.scheduledMonth,payload);confirmingSip=null;await loadMutualFunds();await refreshStories();}catch(cause){sipConfirmError=cause?.message||'Could not save this SIP allocation.';}finally{sipConfirmSaving=false;}}
  async function openFundDetail(id){fundDetail={id};fundDetailStatus='loading';fundDetailError='';try{fundDetail=await getMutualFund(id);fundDetailStatus='ready';}catch(cause){fundDetailStatus='error';fundDetailError=cause?.message||'Could not load this fund.';}}
  function openLumpSum(fund){lumpSumFund=fund;lumpSumError='';lumpSumForm={amount:'',transactionDate:new Date().toISOString().slice(0,10),nav:''};}
  function openHistoryEdit(fund,entry){editingFundTransaction={fund,entry};fundTransactionError='';fundTransactionForm={amount:String(entry.amount||''),transactionDate:entry.transactionDate||'',nav:entry.nav==null?'':String(entry.nav)};}
  async function saveFundTransaction(){const amount=Number(fundTransactionForm.amount),nav=Number(fundTransactionForm.nav);if(!(amount>0)||!fundTransactionForm.transactionDate||!(nav>0)){fundTransactionError='Enter a valid amount, transaction date, and NAV.';return;}fundTransactionSaving=true;fundTransactionError='';try{await updateMutualFundTransaction(editingFundTransaction.fund.id,editingFundTransaction.entry.id,{amount,transactionDate:fundTransactionForm.transactionDate,nav,calculationSource:'USER_ENTERED'});const id=editingFundTransaction.fund.id;editingFundTransaction=null;await Promise.all([loadMutualFunds(),openFundDetail(id),refreshStories()]);}catch(cause){fundTransactionError=cause?.message||'Could not update this investment.';}finally{fundTransactionSaving=false;}}
  async function saveLumpSum(){const amount=Number(lumpSumForm.amount),nav=Number(lumpSumForm.nav);if(!(amount>0)||!lumpSumForm.transactionDate||!(nav>0)){lumpSumError='Enter a positive amount, transaction date, and NAV.';return;}lumpSumSaving=true;try{await createMutualFundLumpSum(lumpSumFund.id,{amount,transactionDate:lumpSumForm.transactionDate,nav,calculationSource:'NAV_ESTIMATED'});lumpSumFund=null;await Promise.all([loadMutualFunds(),refreshStories()]);}catch(cause){lumpSumError=cause?.message||'Could not add this lump sum.';}finally{lumpSumSaving=false;}}
  function navigate(next){view=next;if(next!=='transactions'){selectedDay=null;activityTab='recent';}window.scrollTo({top:0,behavior:'smooth'});}
  function currentLocalMonth(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;}
  function changeMonth(offset){const[y,m]=selectedMonth.split('-').map(Number),next=new Date(Date.UTC(y,m-1+offset,1)).toISOString().slice(0,7);if(next<=currentLocalMonth()){selectedDay=null;dayItems=[];activityTab='recent';onMonthChange(next);}}
  function buildCalendar(monthValue,apiDays){const[y,m]=monthValue.split('-').map(Number),count=new Date(y,m,0).getDate(),leading=(new Date(y,m-1,1).getDay()+6)%7,values=new Map(apiDays.map(x=>[Number(String(x.date).slice(-2)),x])),today=new Date(),current=today.getFullYear()===y&&today.getMonth()+1===m;return{leading,days:Array.from({length:count},(_,i)=>{const day=i+1,v=values.get(day)||{};return{day,totalSpend:Number(v.totalSpend||0),transactionCount:Number(v.transactionCount||0),intensity:Math.max(0,Math.min(4,Number(v.intensity||0))),future:current&&day>today.getDate()};})};}
  async function selectDate(day){if(!day||day.future)return;selectedDay=day.day;activityTab='day';showAll=false;expandedId=null;await loadDay();}
  async function loadDay(){if(selectedDay==null)return;dayStatus='loading';try{const page=await getExpensesForDate(selectedMonth,isoDate(selectedDay),50);dayItems=page.items||page.expenses||[];dayStatus='ready';}catch{dayStatus='error';}}
  async function openStory(story){openedStory=story;storySlide=0;showStoryEvidence=false;const hasReview=(story.cards||[]).some(card=>(card.actions||[]).some(action=>action.type==='OPEN_COMMITMENT_REVIEW'));if(hasReview){commitmentReviewStatus='loading';showCommitmentReview=true;try{const result=await getCommitmentReview(selectedMonth);commitmentReview=result.items||[];commitmentReviewStatus='ready';}catch(cause){commitmentReviewStatus='error';commitmentError=cause?.message||'Could not load payments needing review.';}}}
  function storyHasLoan(story){return isCommitment(story)&&evidenceFor(story,storySlide).some(item=>/loan/i.test(item.category));}
  async function resolveCandidate(transactionId,commitmentId){resolvingCandidate=transactionId;try{await resolveCommitmentReview(transactionId,commitmentId);commitmentReview=commitmentReview.filter(item=>item.transactionId!==transactionId);await refreshStories();if(!commitmentReview.length)showCommitmentReview=false;}catch(cause){commitmentError=cause?.message||'Could not save this review.';}finally{resolvingCandidate=null;}}
  function endStorySwipe(event,length){if(storyTouchStart===null)return;const distance=event.changedTouches[0].clientX-storyTouchStart;if(Math.abs(distance)>45)storySlide=Math.max(0,Math.min(length-1,storySlide+(distance<0?1:-1)));storyTouchStart=null;}
  function endRailSwipe(event,length,rail){if(storyRailTouchStart===null)return;const distance=event.changedTouches[0].clientX-storyRailTouchStart;if(Math.abs(distance)>45){const next=Math.max(0,Math.min(length-1,(rail==='home'?homeStoryIndex:storiesRailIndex)+(distance<0?1:-1)));if(rail==='home')homeStoryIndex=next;else storiesRailIndex=next;}storyRailTouchStart=null;}
  async function startEdit(item){editing=item;editAmount=String(item.amount??'');editDate=localInputDate(transactionDate(item));editCategory=category(item)==='Uncategorised'?'':category(item);editSubcategory=item.subcategory?.name||item.subcategory||'';editMerchantId=String(item.merchantId??item.merchant?.id??'');editAccountId=String(item.accountId??item.account?.id??item.sourceAccountId??'');actionError='';optionsError='';if(optionsStatus==='ready'){selectCurrentReferences(item);return;}optionsStatus='loading';try{const result=await getExpenseOptions();editOptions={categories:result.categories||[],merchants:result.merchants||[],accounts:result.accounts||[]};optionsStatus='ready';selectCurrentReferences(item);}catch(cause){optionsStatus='error';optionsError=cause?.message||'Could not load expense options.';}}
  function selectCurrentReferences(item){if(!editMerchantId){const match=editOptions.merchants.find(option=>option.name?.toLowerCase()===merchant(item).toLowerCase());if(match)editMerchantId=String(match.id);}if(!editAccountId){const current=String(item.account?.name??item.sourceAccount?.name??item.accountName??'').toLowerCase(),match=editOptions.accounts.find(option=>option.name?.toLowerCase()===current);if(match)editAccountId=String(match.id);}}
  function changeEditCategory(event){editCategory=event.currentTarget.value;if(!editSubcategories.includes(editSubcategory))editSubcategory='';}
  async function saveEdit(){const amount=Number(editAmount),merchantId=Number(editMerchantId),accountId=Number(editAccountId);if(!editing||saving||optionsStatus!=='ready'||!Number.isFinite(amount)||amount<=0||!editDate||!editCategory||!editSubcategory||!Number.isFinite(merchantId)||!Number.isFinite(accountId))return;saving=true;actionError='';try{await updateExpense(editing.id,{amount,transactionDate:editDate,category:editCategory,subcategory:editSubcategory,merchantId,accountId});editing=null;await Promise.all([loadDay(),refreshRecent(),refreshCalendar(),refreshStories()]);}catch(cause){actionError=cause?.message||'Could not update the transaction.';}finally{saving=false;}}
  async function confirmDelete(){if(!deleting)return;try{await deleteExpense(deleting.id);deleting=null;await Promise.all([loadDay(),refreshRecent(),refreshCalendar(),refreshStories()]);}catch(cause){actionError=cause?.message||'Could not delete the transaction.';deleting=null;}}
  async function addMissingDate(){if(!selected||addingContext)return;addingContext=true;try{const result=await createMissingDateContext(isoDate(selected.day),data.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone);handoff={...result,date:isoDate(selected.day)};}catch(cause){actionError=cause instanceof ApiError?cause.message:'Could not prepare WhatsApp recording.';}finally{addingContext=false;}}
  async function signOut(){loggingOut=true;try{await logout();try{localStorage.removeItem(`${MONEY_MODULES_CACHE_KEY}.real`);localStorage.removeItem(`${MONEY_MODULES_CACHE_KEY}.demo`);}catch{}onLogout();}catch{loggingOut=false;signOutError='Could not sign out.';}}
  async function switchDemoMode(){if(demoSwitching)return;demoSwitching=true;demoError='';try{await onDemoModeChange(!demoMode);loans=[];mutualFunds=[];stocks=[];actions=[];loanStatus='idle';mutualFundStatus='idle';stockStatus='idle';actionsStatus='idle';fundDetail=null;dayItems=[];selectedDay=null;editOptions={categories:[],merchants:[],accounts:[]};optionsStatus='idle';showMoney=false;await loadActions();}catch(cause){demoError=cause?.message||'Could not switch profiles.';}finally{demoSwitching=false;}}
  onMount(()=>{try{commitmentStyle=localStorage.getItem('money-stories.commitment-style')||'playful';}catch{}loadActions();});
</script>

<AppHeader {connectionStatus} {connectionLabel} onRetry={onRetryConnection} onHome={() => navigate('home')} onProfile={() => navigate('you')} />
<main class="app-shell">
{#if connectionStatus==='offline'}<section class="offline-notice"><span>◌</span><div><strong>{cacheUpdatedAt?'Showing your last saved view':'You’re offline'}</strong><p>{cacheUpdatedAt?'We’ll refresh automatically when the service is back.':'Your layout is ready. Connect once to load your expenses and stories.'}</p></div><button on:click={onRetryConnection}>Retry</button></section>{/if}
{#if view==='home'}
  <section class="app-heading"><div><p class="micro-label">{monthLabel(selectedMonth).toUpperCase()}</p><h1>{greeting()}</h1><p>Here’s how your month is unfolding.</p></div></section>
  <SectionState section={calendarSection} title="Spending overview" retry={refreshCalendar}><button class="spending-hero" on:click={()=>navigate('transactions')}><span>MONTHLY SPENDING</span><strong>{money(data.totalSpend)} <small>spent</small></strong><b>{data.transactionCount||0} transactions · View transactions →</b></button></SectionState>
  <section class="home-section"><div class="section-title"><div><p class="micro-label">YOUR STORIES</p><h2>Small signals, clearly told</h2></div><button class="text-link" on:click={()=>navigate('stories')}>See all</button></div><SectionState section={storiesSection} title="Your stories" retry={refreshStories}>{#if homeStories.length}<div class="story-carousel" aria-label="Your stories"><div class="story-dots" aria-label="Choose a story">{#each homeStories as story,index}<button class:active={index===homeStoryIndex} aria-label={`Show story ${index+1} of ${homeStories.length}: ${storyCardFace(story).heading}`} aria-current={index===homeStoryIndex?'true':undefined} on:click={()=>homeStoryIndex=index}></button>{/each}<span>{homeStoryIndex+1} / {homeStories.length}</span></div><div class="story-carousel-viewport" on:touchstart={event=>(storyRailTouchStart=event.touches[0].clientX)} on:touchend={event=>endRailSwipe(event,homeStories.length,'home')}><div class="story-carousel-track" style={`transform:translateX(calc(${homeStoryIndex} * -92%))`}>{#each homeStories as story,index}<button class={`story-carousel-card ${storyTone(story)}`} class:current={index===homeStoryIndex} on:click={()=>openStory(story)}><span class="story-source">{storySource(story)}</span><strong>{storyCardFace(story).heading}</strong><b>{storyCardFace(story).displayValue}</b><i>›</i></button>{/each}</div></div></div>{:else}<div class="story-rail-empty">Your stories will appear here as you add expenses.</div>{/if}</SectionState></section>
  <section class="home-section"><div class="section-title"><div><p class="micro-label">RECENT ACTIVITY</p><h2>Your latest expenses</h2></div><button class="text-link" on:click={()=>navigate('transactions')}>See all</button></div><div class="compact-list">{#each recentItems.slice(0,3) as item}<button class="row-main" on:click={()=>{navigate('transactions');startEdit(item);}}><div><strong>{merchant(item)}</strong><span>{category(item)} · {dateLabel(transactionDate(item))}</span></div><b>− {money(item.amount)}</b></button>{:else}<p class="empty-copy">No expenses recorded yet.</p>{/each}</div></section>
  <button class="your-money-card" on:click={openMoney}><span>◒</span><div><strong>Your money</strong><small>See your incoming and outgoing plan, only when you’re ready.</small></div><b>Explore ›</b></button>
{:else if view==='transactions'}
  <section class="workspace-heading"><div><p class="micro-label">EXPENSE WORKSPACE</p><h1>Transactions</h1><p>AI-captured expenses, ready for your review.</p></div><label class="month-switcher"><button type="button" on:click={()=>changeMonth(-1)}>←</button><input type="month" value={selectedMonth} max={currentLocalMonth()} on:change={e=>onMonthChange(e.currentTarget.value)}/><button type="button" on:click={()=>changeMonth(1)}>→</button></label></section>
  <SectionState section={calendarSection} title="Spending calendar" retry={refreshCalendar}><section class="month-card"><div class="month-summary"><div><span>Total recorded</span><strong>{money(data.totalSpend)}</strong></div><div><span>Transactions</span><strong>{data.transactionCount||0}</strong></div><div><span>Highest day</span><strong>{money(data.highestSpend)}</strong></div></div><div class="weekdays">{#each ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as d}<span>{d}</span>{/each}</div><div class="calendar">{#each Array(calendar.leading) as _}<span></span>{/each}{#each calendar.days as d}<button class:future={d.future} class:selected={selectedDay===d.day} class={`level-${d.intensity}`} disabled={d.future} on:click={()=>selectDate(d)}>{d.day}</button>{/each}</div><div class="legend"><span>Lower spend</span><div>{#each [0,1,2,3,4] as l}<i class={`level-${l}`}></i>{/each}</div><span>Higher spend</span></div></section></SectionState>
  <section class="activity-panel adaptive-activity"><div class="activity-tabs"><button class:active={activityTab==='recent'} on:click={()=>activityTab='recent'}>Recent</button><button class:active={activityTab==='day'} on:click={()=>activityTab='day'}>{selected?`${selected.day} selected`:'Select a date'}</button></div>{#if activityTab==='day'&&dayStatus==='loading'}<div class="activity-loading">Loading transactions…</div>{:else if activityTab==='day'&&dayStatus==='error'}<div class="section-error"><p>Could not load this date.</p><button on:click={loadDay}>Try again</button></div>{:else}<div class="activity-summary"><p class="micro-label">{activityTab==='recent'?'RECENT EXPENSES':selected?`${selected.day} ${monthLabel(selectedMonth)}`:'SELECT A DATE'}</p><h2>{activityTab==='recent'?`${recentItems.length} recent transactions`:selected?`${selected.transactionCount} transactions · ${money(selected.totalSpend)}`:'Choose a date in the calendar'}</h2></div><div class="compact-list">{#each visibleItems as item}<article class:expanded={expandedId===item.id} class="compact-row"><button class="row-main" on:click={()=>expandedId=expandedId===item.id?null:item.id}><div><strong>{merchant(item)}</strong><span>{category(item)} · {dateLabel(transactionDate(item))}</span></div><div class="row-value"><b>− {money(item.amount)}</b><span class:open={expandedId===item.id} class="row-chevron">⌄</span></div></button>{#if expandedId===item.id}<div class="row-actions"><button on:click={()=>startEdit(item)}>Edit transaction</button><button class="danger" on:click={()=>deleting=item}>Delete</button></div>{/if}</article>{:else}<p class="empty-copy">No transactions for this view.</p>{/each}</div>{#if activeItems.length>5}<button class="view-all" on:click={()=>showAll=!showAll}>{showAll?'Show fewer ↑':`View all ${activeItems.length} transactions ↓`}</button>{/if}{/if}</section>
  <button class="wide-button" disabled={!selected||addingContext} on:click={addMissingDate}>{addingContext?'Preparing WhatsApp…':selected?'+ Add missing expense':'Select a date to add an expense'}</button><button class="cleanup-card" on:click={()=>showNormalization=true}><span>✦</span><div><strong>Expense cleanup</strong><small>Fix merchant and account names captured by AI.</small></div><b>Open ›</b></button>
{:else if view==='stories'}
  <section class="workspace-heading"><div><p class="micro-label">YOUR MONEY, EXPLAINED</p><h1>Stories</h1><p>Insights across the information you choose to share.</p></div></section><div class="story-filters">{#each ['All','Spending','Investing','Planning'] as filter}<button class:active={storyFilter===filter} on:click={()=>{storyFilter=filter;storiesRailIndex=0;}}>{filter}</button>{/each}</div><div class="commitment-style-control"><span>Commitment style</span><button class:active={commitmentStyle==='calm'} on:click={()=>setCommitmentStyle('calm')}>Calm</button><button class:active={commitmentStyle==='playful'} on:click={()=>setCommitmentStyle('playful')}>Playful ✨</button></div><SectionState section={storiesSection} title="Stories" retry={refreshStories}>{#if filteredStories.length}<div class="story-carousel story-carousel-full" aria-label={`${storyFilter} stories`}><div class="story-dots" aria-label="Choose a story">{#each filteredStories as story,index}<button class:active={index===storiesRailIndex} aria-label={`Show story ${index+1} of ${filteredStories.length}: ${storyCardFace(story).heading}`} aria-current={index===storiesRailIndex?'true':undefined} on:click={()=>storiesRailIndex=index}></button>{/each}<span>{storiesRailIndex+1} / {filteredStories.length}</span></div><div class="story-carousel-viewport" on:touchstart={event=>(storyRailTouchStart=event.touches[0].clientX)} on:touchend={event=>endRailSwipe(event,filteredStories.length,'full')}><div class="story-carousel-track" style={`transform:translateX(calc(${storiesRailIndex} * -92%))`}>{#each filteredStories as story,index}<button class={`story-carousel-card ${storyTone(story)}`} class:commitment-card={isCommitment(story)} class:playful={isCommitment(story)&&commitmentStyle==='playful'} class:current={index===storiesRailIndex} on:click={()=>openStory(story)}><span class="story-source">{storySource(story)}</span>{#if storyIcon(story)}<span class="commitment-icon">{storyIcon(story)}</span>{/if}<strong>{storyHeading(story)}</strong><b>{storyCardFace(story).displayValue}</b><i>›</i></button>{/each}</div></div></div>{:else}<div class="empty-state"><span>✦</span><h2>No {storyFilter.toLowerCase()} stories yet</h2><p>As you choose to add more information, relevant stories will appear here.</p></div>{/if}</SectionState>
{:else}
  <ProfileSettings {demoMode} {demoSwitching} {demoError} {loggingOut} {signOutError} {storyControls} onNavigate={navigate} onOpenMoney={openMoney} onDemoModeChange={switchDemoMode} onSignOut={signOut} />
{/if}
</main>
<BottomNav {view} onNavigate={navigate} />

<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if showMoney}
  <div class="modal-backdrop" on:click={closeMoney} on:keydown={(event)=>event.key==='Escape'&&closeMoney()} role="presentation">
    <section class="modal money-modal" on:click|stopPropagation role="dialog" aria-modal="true" tabindex="-1">
      <button class="close" on:click={closeMoney}>×</button>
      <p class="micro-label">OPTIONAL, PRIVATE, YOURS</p><h2>Build your complete money picture</h2>
      <p class="module-reassurance">You choose what to add. Nothing is required, and you can remove a module anytime.</p>
      <section class="income-module"><div class="loans-heading"><div><strong>Salary outlook</strong><small>Private estimate — never treated as your account balance</small></div><span class="verified-pill">Optional</span></div>{#if incomeStatus==='loading'}<p>Loading your private outlook…</p>{:else if incomeStatus==='error'}<div class="loan-state error"><span>{incomeError}</span><button on:click={loadIncomeOutlook}>Try again</button></div>{:else if incomeOutlook.salary}<div class="income-summary masked"><span>Salary saved</span><strong>{incomeOutlook.salary.maskedValue}</strong><button class="income-edit" on:click={openIncomeFlow} aria-label="Update salary outlook" title="Update salary outlook">🔧</button><small>Masked before it reaches this screen.</small></div>{:else}<div class="income-summary"><strong>Start with a range</strong><small>Only you decide whether to share a range or an exact amount.</small></div><button class="add-fund-row" on:click={openIncomeFlow}>Set up salary outlook</button>{/if}</section>
      <section class="loans-module" data-testid="monthly-commitments-section"><div class="loans-heading"><div><strong>Monthly commitments</strong><small>Rent, bills, subscriptions and other repeatable obligations</small></div></div>{#if commitmentStatus==='loading'}<p class="loan-state">Loading commitments…</p>{:else if commitmentStatus==='error'}<div class="loan-state error"><span>{commitmentError}</span><button on:click={loadCommitments}>Try again</button></div>{:else if commitments.length}{#each commitments as commitment}<article class="loan-row" data-testid={`monthly-commitment-${commitment.id}`} class:due-recurring={commitment.currentOccurrence?.status==='DUE'}><span>↻</span><div><strong class="loan-name">{commitment.label}<button class="loan-edit" on:click={()=>openCommitmentForm(commitment)} aria-label={`Edit ${commitment.label}`} title="Edit monthly commitment">🔧</button><button class="loan-delete" on:click={()=>removeCommitment(commitment)} aria-label={`Delete ${commitment.label}`} title="Delete monthly commitment" disabled={commitmentDeletingId!==null}>{commitmentDeletingId===commitment.id?'…':'🗑'}</button></strong><small>{commitment.amountMode==='RECENT_BILL_ESTIMATE'?'Recent-bill estimate':'Monthly planning amount'}{commitment.dueDay?` · due around the ${commitment.dueDay}`:''}</small></div><div><b>{money(commitment.planningAmount)}/mo</b><small>{commitment.currentOccurrence?.status==='COMPLETED'?'done':commitment.status.toLowerCase()}</small></div>{#if commitment.currentOccurrence?.status==='DUE'}<div class="loan-due-action"><DueReminder detail={`Due now · ${money(commitment.planningAmount)}`} actionLabel="Mark commitment done" onAction={()=>markCommitmentDone(commitment)}/></div>{:else if commitment.currentOccurrence?.status==='COMPLETED'}<div class="loan-due-action"><small>Done on {dateLabel(`${commitment.currentOccurrence.completedAt}T12:00:00`)}</small></div>{/if}</article>{/each}{:else}<p class="loan-state">No recurring commitments yet.</p>{/if}<button class="add-loan-row" on:click={()=>openCommitmentForm()}>＋ Add a monthly commitment</button></section>
      <section class="loans-module"><div class="loans-heading"><div><strong>Credit cards</strong><small>Turn captured card spending into the bill due next month</small></div></div>{#if creditCardStatus==='loading'}<p class="loan-state">Loading credit cards…</p>{:else if creditCardStatus==='error'}<div class="loan-state error"><span>{creditCardError}</span><button on:click={loadCreditCards}>Try again</button></div>{:else if creditCards.length}{#each creditCards as card}<article class="loan-row"><span>▣</span><div><strong class="loan-name">{card.cardName}<button class="loan-edit" on:click={()=>openCreditCardForm(card)} aria-label={`Edit ${card.cardName}`} title="Edit credit card">🔧</button></strong><small>{card.issuerName} · captured as {card.accountName}</small></div><div><b>Due {card.dueDay}</b><small>Statement {card.statementDay}</small></div></article>{/each}{:else}<p class="loan-state">Add a card once it appears as an account in your captured expenses.</p>{/if}<button class="add-loan-row" on:click={()=>openCreditCardForm()}>＋ Add a credit card</button></section>
      {#each [['◒','Emergency fund','Track your safety cushion'],['◎','Goals','Plan for what matters'],['▤','Budgets','Set gentle spending limits']] as module}
        <button class="module-row" on:click={closeMoney}><span>{module[0]}</span><div><strong>{module[1]}</strong><small>{module[2]}</small></div><b>Coming soon</b></button>
      {/each}
      <section class="mutual-funds-module"><div class="loans-heading"><div><strong>Mutual funds</strong><small>Portfolio value from the latest available NAV</small></div><span class="verified-pill">Scheme API</span></div>{#if mutualFundStatus==='loading'}<p>Loading your funds…</p>{:else if mutualFundStatus==='error'}<div class="loan-state error"><span>{mutualFundError}</span><button on:click={loadMutualFunds}>Try again</button></div>{:else if mutualFunds.length}<section class="portfolio-total"><span>Total portfolio value</span>{#if mutualPortfolio.current!==null}<strong>{money(mutualPortfolio.current)}</strong><small class:positive={Number(mutualPortfolio.pnl)>=0} class:negative={Number(mutualPortfolio.pnl)<0}>{mutualPortfolio.pnl>=0?'+':''}{money(mutualPortfolio.pnl)} overall P&amp;L</small>{:else}<strong>{money(mutualPortfolio.invested)}</strong><small>Current valuation is temporarily unavailable</small>{/if}</section><div class="fund-card-list">{#each mutualFunds as fund}<button class={`fund-card ${fundAccent(fund.id)}`} on:click={()=>openFundDetail(fund.id)} aria-label={`Open ${fund.schemeName} details`}><span class="fund-card-orb"></span><div class="fund-card-title"><strong>{fund.schemeName}</strong><span class="fund-delete" role="button" tabindex="0" aria-label={`Delete ${fund.schemeName}`} title="Delete mutual fund" on:click|stopPropagation={()=>removeMutualFund(fund)} on:keydown|stopPropagation={(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();removeMutualFund(fund);}}}>{mutualFundDeletingId===fund.id?'…':'🗑'}</span><small>{fundSubtitle(fund.schemeName)}</small></div>{#if fund.currentValue!==null}<div class="fund-card-values"><div class:positive={Number(fund.profitOrLoss)>=0} class:negative={Number(fund.profitOrLoss)<0}><span>P&amp;L</span><b>{Number(fund.profitOrLoss)>=0?'+':''}{compactMoney(fund.profitOrLoss)}</b><small>{Number(fund.profitOrLossPercent)>=0?'+':''}{Number(fund.profitOrLossPercent).toFixed(2)}%</small></div><div><span>Invested</span><b>{compactMoney(fund.invested)}</b></div><div><span>Current</span><b>{compactMoney(fund.currentValue)}</b></div></div><p class="fund-card-nav">Latest NAV {moneyDecimal(fund.latestNav)} {#if !fund.activeSip}<span class="stock-recurring-bell" role="button" tabindex="0" aria-label={`Set SIP for ${fund.schemeName}`} title="Set SIP" on:click|stopPropagation={()=>openFundSipPlan(fund)} on:keydown|stopPropagation={(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openFundSipPlan(fund);}}}>🔔</span>{/if}</p>{:else}<p class="fund-valuation-unavailable">Current valuation is temporarily unavailable. Your invested amount is {money(fund.invested)}.</p>{/if}<footer><span class="fund-sip-summary">{fund.activeSip?`1 SIP · ${compactMoney(fund.activeSip.amount)} on the ${fund.activeSip.day}${fund.activeSip.day===1?'st':fund.activeSip.day===2?'nd':fund.activeSip.day===3?'rd':'th'} of every month`:'No active SIP'}</span><span class="fund-actions"><span>View details →</span><span class="fund-lump-sum" role="button" tabindex="0" on:click|stopPropagation={()=>openLumpSum(fund)}>＋ Lump sum</span></span></footer>{#if fund.currentSip?.status==="DUE"}<DueReminder testId={`mutual-fund-sip-${fund.id}`} detail={`Due now · ${money(fund.currentSip.amount)}`} actionLabel="Confirm allocation" onAction={()=>openSipConfirmation(fund,fund.currentSip)}/>{/if}</button>{/each}</div>{:else}<p>Choose one verified scheme, then add its existing holding, an SIP, or occasional lump sums whenever you need.</p>{/if}<button class="add-fund-row" on:click={openMutualFundForm}>＋ Add a mutual fund</button></section>
      <section class="mutual-funds-module stocks-module">
        <div class="loans-heading"><div><strong>Stocks</strong><small>Portfolio value from the latest available market price</small></div><span class="verified-pill">Market data</span></div>
        {#if stockStatus==='loading'}<p>Loading your stocks…</p>
        {:else if stockStatus==='error'}<div class="loan-state error"><span>{stockError}</span><button on:click={loadStocks}>Try again</button></div>
        {:else if stocks.length}
          <section class="portfolio-total"><span>Total stock value</span>{#if stockPortfolio.current!==null}<strong>{money(stockPortfolio.current)}</strong><small class:positive={stockPortfolio.pnl>=0} class:negative={stockPortfolio.pnl<0}>{stockPortfolio.pnl>=0?'+':''}{money(stockPortfolio.pnl)} overall P&amp;L</small>{:else}<strong>{money(stockPortfolio.invested)}</strong><small>Current valuation is temporarily unavailable</small>{/if}</section>
          <div class="fund-card-list">{#each stocks as stock}<article class={`fund-card ${fundAccent(stock.id)}`} data-testid={`stock-card-${stock.id}`} class:due-stock={String(stock.id)===String(highlightedStockId)}>
            <span class="fund-card-orb"></span><div class="fund-card-title"><strong>{stock.name}</strong><span class="fund-delete" role="button" tabindex="0" aria-label={`Delete ${stock.name}`} title="Delete stock" on:click={()=>removeStock(stock)} on:keydown={(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();removeStock(stock);}}}>{stockDeletingId===stock.id?'…':'🗑'}</span><small>{stock.symbol}{stock.exchange?` · ${stock.exchange}`:''}</small></div>
            {#if stock.currentValue!==null}<div class="fund-card-values"><div class:positive={Number(stock.profitOrLoss)>=0} class:negative={Number(stock.profitOrLoss)<0}><span>P&amp;L</span><b>{Number(stock.profitOrLoss)>=0?'+':''}{compactMoney(stock.profitOrLoss)}</b><small>{Number(stock.profitOrLossPercent)>=0?'+':''}{Number(stock.profitOrLossPercent).toFixed(2)}%</small></div><div><span>Invested</span><b>{compactMoney(stock.invested)}</b></div><div><span>Current</span><b>{compactMoney(stock.currentValue)}</b></div></div><p class="fund-card-nav">Latest price {moneyDecimal(stock.latestPrice)} · {Number(stock.quantity).toFixed(3)} shares <button class="stock-recurring-bell" aria-label={`Set monthly recurring plan for ${stock.name}`} title="Set monthly recurring plan" on:click={()=>openStockPlan(stock)}>🔔</button></p>{:else}<p class="fund-valuation-unavailable">Current price is temporarily unavailable. Your invested amount is {money(stock.invested)}.</p>{/if}
            <footer><span class="fund-sip-summary">{stock.activeMonthlyPlan?`Monthly plan · ${compactMoney(stock.activeMonthlyPlan.amount)} on the ${stock.activeMonthlyPlan.day}${stock.activeMonthlyPlan.day===1?'st':stock.activeMonthlyPlan.day===2?'nd':stock.activeMonthlyPlan.day===3?'rd':'th'}`:'No monthly plan'}</span><button class="stock-detail-link" on:click={()=>openStockDetail(stock.id)}>View details →</button></footer>
            {#if stock.currentMonthlyPlan?.status==='DUE'}<DueReminder testId={`stock-monthly-plan-${stock.id}`} detail={`Due now · ${money(stock.currentMonthlyPlan.amount)}`} actionLabel="Confirm allocation" onAction={()=>{stockPlanConfirmationTarget=stock;stockPlanConfirmation={amount:String(stock.currentMonthlyPlan.amount),price:String(stock.latestPrice||'')}}}/>{/if}
          </article>{/each}</div>
        {:else}<p>Search a listed stock, then add the shares and amount you already invested.</p>{/if}
        <button class="add-fund-row" on:click={openStockForm}>＋ Add a stock</button>
      </section>
      <section class="loans-module" data-testid="loans-section"><div class="loans-heading"><div><strong>Loans</strong><small>Track repayments and monthly commitments</small></div>{#if activeLoans.length}<div class="loan-total"><span>Total monthly EMI</span><b>{money(totalMonthlyEmi)}/mo</b></div>{/if}</div>
        {#if loanStatus==='loading'}<p class="loan-state">Loading your loans…</p>{:else if loanStatus==='error'}<div class="loan-state error"><span>{loanError}</span><button on:click={loadLoans}>Try again</button></div>{:else if activeLoans.length}{#each activeLoans as loan}{@const schedule=loanSchedule(loan)}<article class="loan-row" class:due-loan={String(loan.id)===String(highlightedLoanId)}><span>₹</span><div><strong class="loan-name">{loan.loanName}<button class="loan-edit" on:click={()=>openLoanForm(loan)} aria-label={`Edit ${loan.loanName}`} title="Edit loan">🔧</button><button class="loan-delete" on:click={()=>removeLoan(loan)} aria-label={`Delete ${loan.loanName}`} title="Delete loan" disabled={loanDeletingId!==null}>{loanDeletingId===loan.id?'…':'🗑'}</button></strong><small>{loan.lenderName} · {loan.loanType.replaceAll('_',' ')} · {loan.totalTenureMonths} months</small></div><div><b>{money(loan.monthlyEmiAmount)}/mo</b><small>{money(loan.originalPrincipal)} principal</small></div>{#if schedule}<div class="loan-progress"><div><span>{schedule.due} of {schedule.tenure} historical EMI months completed</span></div><i style={`--loan-progress:${schedule.percent}%`}></i></div>{/if}{#each loan.emiOccurrences||[] as occurrence}<div class:due={occurrence.status==='DUE'} data-testid={`loan-emi-${occurrence.month}`}><strong>{new Intl.DateTimeFormat(undefined,{month:'long'}).format(new Date(`${occurrence.dueDate}T12:00:00`))}{occurrence.month==='2026-04'?' EMI':''}</strong> <span>{occurrence.status}</span><small>{new Intl.DateTimeFormat(undefined,{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${occurrence.dueDate}T12:00:00`))} · {money(occurrence.plannedAmount)}</small>{#if occurrence.status==='PAID'}<small>Paid amount: {money(occurrence.paidAmount)} · Paid on: {new Intl.DateTimeFormat(undefined,{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${occurrence.paidAt}T12:00:00`))}</small>{:else if occurrence.status==='DUE'}<DueReminder detail={`Due now · ${money(occurrence.plannedAmount)}`} actionLabel={`Mark ${new Intl.DateTimeFormat(undefined,{month:'long'}).format(new Date(`${occurrence.dueDate}T12:00:00`))} EMI paid`} onAction={()=>payLoanEmi(loan,occurrence)}/>{/if}</div>{/each}{#if String(loan.id)===String(highlightedLoanId)&&highlightedLoanAction}<div class="loan-due-action"><strong>Final EMI due</strong><p>Confirm you paid the final EMI before closing this loan.</p><button class="primary" data-testid="mark-final-emi-paid" disabled={completingActionId!==null} on:click={()=>completeOpenAction(highlightedLoanAction)}>{completingActionId===highlightedLoanAction.id?'Marking loan closed…':'Mark final EMI paid'}</button></div>{/if}</article>{/each}{:else}<p class="loan-state">No active loans.</p>{/if}
        {#if closedLoans.length}<button class="closed-loans-toggle" data-testid="closed-loans-toggle" aria-expanded={showClosedLoans} on:click={()=>showClosedLoans=!showClosedLoans}>Closed loans · {closedLoans.length}<span>{showClosedLoans?'⌃':'⌄'}</span></button>{#if showClosedLoans}<div class="closed-loans-list">{#each closedLoans as loan}<ClosedLoanRow {loan} {money}/>{/each}</div>{/if}{/if}
        <button class="add-loan-row" on:click={()=>openLoanForm()}>＋ Add another loan</button>
      </section>
      <p class="module-footnote">These modules use normal forms—not AI cleanup—and only inform stories if you turn that on.</p>
    </section>
  </div>
{/if}
{#if showCommitmentForm}<div class="modal-backdrop"><section class="modal loan-form" role="dialog" aria-modal="true"><button class="close" on:click={()=>showCommitmentForm=false}>×</button><p class="micro-label">MONTHLY COMMITMENT</p><h2>{commitmentEditingId===null?'Add a repeatable obligation':'Edit monthly commitment'}</h2><p class="module-reassurance">This is a planning estimate, not proof that a bill was paid.</p><label>Name<input bind:value={commitmentForm.label} placeholder="e.g. Home rent" maxlength="120"/></label><label>Monthly planning amount<input type="number" inputmode="decimal" min="0.01" bind:value={commitmentForm.planningAmount}/></label><label>Expected day <span class="optional">Optional</span><input type="number" min="1" max="28" bind:value={commitmentForm.dueDay}/></label><label>Amount basis<select bind:value={commitmentForm.amountMode}><option value="FIXED">Fixed amount</option><option value="USER_ESTIMATE">My estimate</option></select></label>{#if commitmentError}<p class="form-error">{commitmentError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>showCommitmentForm=false}>Cancel</button><button class="primary" on:click={saveCommitment} disabled={commitmentSaving}>{commitmentSaving?'Saving…':commitmentEditingId===null?'Add commitment':'Save changes'}</button></div></section></div>{/if}
{#if showCreditCardForm}<div class="modal-backdrop"><section class="modal loan-form" role="dialog" aria-modal="true"><button class="close" on:click={()=>showCreditCardForm=false}>×</button><p class="micro-label">CREDIT-CARD BILLING</p><h2>{creditCardEditingId===null?'Add a credit card':'Edit credit card'}</h2><p class="module-reassurance">We add only expenses captured against this account between statement dates to the bill due in that month.</p><label>Captured account<select bind:value={creditCardForm.accountReferenceId}><option value="" disabled>Select the card account</option>{#each editOptions.accounts as account}<option value={String(account.id)}>{account.name}</option>{/each}</select></label><label>Card name<input bind:value={creditCardForm.cardName} placeholder="e.g. Millennia" maxlength="120"/></label><label>Issuer / vendor<input bind:value={creditCardForm.issuerName} placeholder="e.g. HDFC Bank" maxlength="120"/></label><label>Bill generation day<input type="number" min="1" max="28" bind:value={creditCardForm.statementDay}/></label><label>Payment due day<input type="number" min="1" max="28" bind:value={creditCardForm.dueDay}/></label>{#if creditCardError}<p class="form-error">{creditCardError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>showCreditCardForm=false}>Cancel</button><button class="primary" on:click={saveCreditCard} disabled={creditCardSaving||optionsStatus!=='ready'}>{creditCardSaving?'Saving…':creditCardEditingId===null?'Add credit card':'Save changes'}</button></div></section></div>{/if}
{#if showIncomeFlow}<div class="modal-backdrop income-flow-backdrop"><section class="modal income-flow" role="dialog" aria-modal="true"><button class="close" on:click={()=>showIncomeFlow=false}>×</button><p class="micro-label">PRIVATE SALARY CONTEXT</p><h2>What range feels comfortable to share?</h2><p class="module-reassurance">A range is enough. This is not a request for a payslip, and it never changes your balance.</p><div class="range-options">{#each ['UNDER_25000','FROM_25000_TO_50000','FROM_50000_TO_100000','FROM_100000_TO_200000','OVER_200000'] as range}<button class:active={salaryForm.salaryRange===range&&salaryForm.salaryVisibility==='RANGE'} on:click={()=>{salaryForm.salaryVisibility='RANGE';salaryForm.salaryRange=range;}}>{incomeRangeLabel(range)}</button>{/each}</div><button class="text-link income-exact-toggle" on:click={()=>salaryForm.salaryVisibility=salaryForm.salaryVisibility==='EXACT'?'RANGE':'EXACT'}>{salaryForm.salaryVisibility==='EXACT'?'Use a range instead':'I’m comfortable sharing the exact amount'}</button>{#if salaryForm.salaryVisibility==='EXACT'}<label>Monthly take-home salary<input type="number" min="1" inputmode="decimal" bind:value={salaryForm.exactMonthlySalary} placeholder="Optional exact amount"/></label>{/if}<label>How often does it arrive?<select bind:value={salaryForm.salaryFrequency}>{#each ['MONTHLY','TWICE_MONTHLY','WEEKLY','IRREGULAR'] as frequency}<option value={frequency}>{frequency.replaceAll('_',' ').toLowerCase()}</option>{/each}</select></label>{#if incomeError}<p class="form-error">{incomeError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>{salaryForm.salaryVisibility='SKIPPED';saveSalary();}} disabled={incomeSaving}>Skip for now</button><button class="primary" on:click={saveSalary} disabled={incomeSaving}>{incomeSaving?'Saving…':'Save salary outlook'}</button></div></section></div>{/if}
{#if showLoanForm}
  <div class="modal-backdrop loan-form-backdrop" role="presentation"><section class="modal loan-form" role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>showLoanForm=false}>×</button><p class="micro-label">LOAN DETAILS</p><h2>{loanEditingId==null?'Add a loan':'Edit loan'}</h2><p class="module-reassurance">Your loan information is stored securely in your account.</p><label>Loan name<input bind:value={loanForm.loanName} placeholder="e.g. HDFC Home Loan" maxlength="255" /></label><label>Loan type<select bind:value={loanForm.loanType}>{#each ['HOME','VEHICLE','PERSONAL','EDUCATION','CREDIT_CARD_EMI','OTHER'] as type}<option value={type}>{type.replaceAll('_',' ')}</option>{/each}</select></label><label>Original loan principal<input type="number" inputmode="decimal" min="1" bind:value={loanForm.originalPrincipal} placeholder="e.g. 4200000" /></label><label>Monthly EMI amount<input type="number" inputmode="decimal" min="1" bind:value={loanForm.monthlyEmiAmount} placeholder="e.g. 38600" /></label><label>Total tenure in months<input type="number" inputmode="numeric" min="1" bind:value={loanForm.totalTenureMonths} placeholder="e.g. 240" /></label><label>First EMI due date<input type="date" bind:value={loanForm.firstEmiDueDate} /></label><label>Bank / lender<input bind:value={loanForm.lenderName} placeholder="e.g. HDFC Bank" maxlength="255" /></label><label>Notes <span class="optional">Optional</span><input bind:value={loanForm.notes} placeholder="e.g. Primary residence" /></label>{#if loanError}<p class="form-error">{loanError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>showLoanForm=false}>Cancel</button><button class="primary" on:click={saveLoan} disabled={loanSaving}>{loanSaving?'Saving…':loanEditingId==null?'Add loan':'Save changes'}</button></div></section></div>
{/if}
{#if showMutualFundForm}
  <div class="modal-backdrop fund-form-backdrop" role="presentation"><section class="modal fund-form" role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>showMutualFundForm=false}>×</button>
    {#if fundSaved}<div class="fund-success"><span>✓</span><p class="micro-label">{fundForm.hasSip==='YES'?'SIP READY':'FUND ADDED'}</p><h2>{fundForm.hasSip==='YES'?'Your SIP is set up':'Your fund is ready'}</h2><p>{fundForm.hasSip==='YES'?`${money(fundForm.sipAmount)} will be tracked monthly for ${selectedScheme.schemeName}. The first occurrence will be due in ${monthLabel(fundForm.startMonth)}.`:`${selectedScheme.schemeName} is ready for occasional lump sums. You can set up a SIP later from its bell button.`}</p><button class="primary" on:click={()=>showMutualFundForm=false}>Done</button></div>
    {:else}<p class="micro-label">MUTUAL FUND</p><h2>Add a mutual fund</h2><p class="module-reassurance">Search the official scheme master. A returned name is one verified fund, plan and option.</p>
      <div class="fund-section"><span class="fund-section-label">1 · FUND</span><label class="scheme-picker">Search and select scheme<input value={schemeQuery} on:focus={()=>showSchemeMenu=true} on:input={e=>searchSchemes(e.currentTarget.value)} placeholder="Type at least 2 characters" autocomplete="off" />{#if showSchemeMenu}<div class="scheme-menu">{#if schemeSearchStatus==='loading'}<p>Searching schemes…</p>{:else if schemeQuery.trim().length<2}<p>Type at least 2 characters to search.</p>{:else}{#each schemeResults as scheme}<button type="button" on:mousedown|preventDefault={()=>selectScheme(scheme)}><strong>{scheme.schemeName}</strong><small>Scheme code {scheme.schemeCode} · {scheme.latestNav==null?'Latest NAV unavailable':`Latest NAV ${moneyDecimal(scheme.latestNav)}`}</small></button>{:else}<p>No matching scheme found.</p>{/each}{/if}</div>{/if}</label>{#if selectedScheme}<div class="scheme-validated"><span>✓</span><div><strong>Verified by scheme master</strong><small>Code {selectedScheme.schemeCode} · {selectedScheme.latestNav==null?'Latest NAV unavailable':`Latest NAV ${moneyDecimal(selectedScheme.latestNav)}`}</small></div></div>{/if}</div>
      <div class="fund-section"><span class="fund-section-label">2 · SIP <em>OPTIONAL</em></span><fieldset><legend>Do you have an actual SIP for this fund?</legend><label class="choice"><input type="radio" bind:group={fundForm.hasSip} value="YES" /> Yes</label><label class="choice"><input type="radio" bind:group={fundForm.hasSip} value="NO" /> No</label></fieldset>{#if fundForm.hasSip==='YES'}<label>Monthly SIP amount<input type="number" inputmode="decimal" min="1" bind:value={fundForm.sipAmount} /></label><div class="fund-field-pair"><label>SIP date<select bind:value={fundForm.sipDate}>{#each Array(28) as _,index}<option value={index+1}>{index+1}{index===0?'st':index===1?'nd':index===2?'rd':'th'} of every month</option>{/each}</select></label><label>Start month<input type="month" bind:value={fundForm.startMonth} /></label></div>{/if}</div>
      <div class="fund-section"><span class="fund-section-label">3 · EXISTING HOLDING <em>OPTIONAL</em></span><fieldset><legend>Do you already hold this fund?</legend><label class="choice"><input type="radio" bind:group={fundForm.hasHolding} value="NO" /> No</label><label class="choice"><input type="radio" bind:group={fundForm.hasHolding} value="YES" /> Yes</label></fieldset>{#if fundForm.hasHolding==='YES'}<div class="fund-field-pair"><label>Current units<input type="number" inputmode="decimal" min="0.001" step="0.001" bind:value={fundForm.currentUnits} /></label><label>Total amount invested<input type="number" inputmode="decimal" min="0.01" bind:value={fundForm.totalInvested} /></label></div><p class="fund-disclaimer">Average purchase cost is calculated by the backend after the opening balance is recorded.</p>{/if}</div>
      {#if fundError}<p class="form-error">{fundError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>showMutualFundForm=false}>Cancel</button><button class="primary" on:click={saveMutualFund} disabled={fundSaving}>{fundSaving?'Creating…':'Add mutual fund'}</button></div>
    {/if}</section></div>
{/if}
{#if showStockForm}
  <div class="modal-backdrop fund-form-backdrop" role="presentation"><section class="modal fund-form" role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>showStockForm=false}>×</button><p class="micro-label">STOCK HOLDING</p><h2>Add a stock</h2><p class="module-reassurance">Search market symbols, then record the shares and total amount you already invested. Editing and selling will follow in a later update.</p><div class="fund-section"><span class="fund-section-label">1 · STOCK</span><label class="scheme-picker">Search and select stock<input value={stockQuery} on:input={e=>findStocks(e.currentTarget.value)} placeholder="Type at least 2 characters" autocomplete="off" />{#if stockQuery.trim().length>=2&&!selectedStock}<div class="scheme-menu">{#if stockSearchStatus==='loading'}<p>Searching stock symbols…</p>{:else if stockSearchStatus==='error'}<p>Could not search stocks.</p>{:else}{#each stockResults as stock}<button type="button" on:mousedown|preventDefault={()=>selectStock(stock)}><strong>{stock.name||stock.symbol}</strong><small>{stock.symbol}{stock.exchange?` · ${stock.exchange}`:''} · {stock.latestPrice==null?'Latest price unavailable':`Latest price ${moneyDecimal(stock.latestPrice)}`}</small></button>{:else}<p>No matching listed stock found.</p>{/each}{/if}</div>{/if}</label>{#if selectedStock}<div class="scheme-validated"><span>✓</span><div><strong>Verified market symbol</strong><small>{selectedStock.symbol}{selectedStock.exchange?` · ${selectedStock.exchange}`:''} · {selectedStock.latestPrice==null?'Latest price unavailable':`Latest price ${moneyDecimal(selectedStock.latestPrice)}`}</small></div></div>{/if}</div><div class="fund-section"><span class="fund-section-label">2 · HOLDING</span><div class="fund-field-pair"><label>Shares held<input type="number" inputmode="decimal" min="0.001" step="0.001" bind:value={stockForm.quantity} /></label><label>Total amount invested<input type="number" inputmode="decimal" min="0.01" bind:value={stockForm.totalInvested} /></label></div></div>{#if stockError}<p class="form-error">{stockError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>showStockForm=false}>Cancel</button><button class="primary" on:click={saveStock} disabled={stockSaving}>{stockSaving?'Adding…':'Add stock'}</button></div></section></div>
{/if}
{#if fundSipTarget}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-form" role="dialog" aria-modal="true"><button class="close" on:click={()=>fundSipTarget=null}>×</button><p class="micro-label">MONTHLY SIP</p><h2>Set up SIP for {fundSipTarget.schemeName}</h2><p class="module-reassurance">This creates a monthly plan. Occasional lump sums remain separate.</p><label>Monthly amount<input type="number" min="0.01" bind:value={fundSipForm.amount}/></label><label>SIP date<input type="number" min="1" max="28" bind:value={fundSipForm.day}/></label><label>Start month<input type="month" bind:value={fundSipForm.startMonth}/></label>{#if fundError}<p class="form-error">{fundError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>fundSipTarget=null}>Cancel</button><button class="primary" on:click={saveFundSipPlan} disabled={fundSipSaving}>{fundSipSaving?'Saving…':'Save SIP'}</button></div></section></div>{/if}
{#if stockPlanTarget}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-form" role="dialog" aria-modal="true"><button class="close" on:click={()=>stockPlanTarget=null}>×</button><p class="micro-label">MONTHLY ETF PLAN</p><h2>Plan {stockPlanTarget.name}</h2><label>Monthly amount<input type="number" min="0.01" bind:value={stockPlanForm.amount}/></label><label>Investment day<input type="number" min="1" max="28" bind:value={stockPlanForm.day}/></label><label>Start month<input type="month" bind:value={stockPlanForm.startMonth}/></label><div class="modal-actions"><button class="secondary" on:click={()=>stockPlanTarget=null}>Cancel</button><button class="primary" on:click={saveStockPlan} disabled={stockPlanSaving}>{stockPlanSaving?'Saving…':'Save monthly plan'}</button></div></section></div>{/if}
{#if stockPlanConfirmationTarget}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-form" role="dialog" aria-modal="true"><button class="close" on:click={()=>stockPlanConfirmationTarget=null}>×</button><p class="micro-label">CONFIRM ETF INVESTMENT</p><h2>Was this investment processed?</h2><label>Amount invested<input type="number" min="0.01" bind:value={stockPlanConfirmation.amount}/></label><label>Executed market price<input type="number" min="0.0001" bind:value={stockPlanConfirmation.price}/></label><div class="modal-actions"><button class="secondary" on:click={()=>stockPlanConfirmationTarget=null}>Cancel</button><button class="primary" on:click={confirmStockPlan}>Confirm investment</button></div></section></div>{/if}
{#if stockDetail}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-detail" role="dialog" aria-modal="true"><button class="close" on:click={()=>stockDetail=null}>×</button>{#if stockDetailStatus==='loading'}<h2>Loading stock details…</h2>{:else if stockDetailStatus==='error'}<h2>Couldn’t load this stock</h2>{:else}<p class="micro-label">STOCK DETAILS</p><h2>{stockDetail.stock.name}</h2><div class="detail-grid"><div><span>Invested</span><b>{money(stockDetail.stock.invested)}</b></div><div><span>Shares</span><b>{Number(stockDetail.stock.quantity).toFixed(3)}</b></div></div><section class="investment-history"><h3>Investment history</h3>{#each stockDetail.history as entry}<div class="investment-history-row"><span>{dateLabel(entry.transactionDate)}</span><strong>{entry.kind==='SIP'?'Monthly ETF purchase':'Opening holding'}</strong><span class="history-amount"><b>{money(entry.amount)}</b></span><small>Price {moneyDecimal(entry.executionPrice)} · {Number(entry.units).toFixed(3)} shares</small></div>{/each}</section>{/if}</section></div>{/if}
<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if fundDetail}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-detail" role="dialog" aria-modal="true"><button class="close" on:click={()=>fundDetail=null}>×</button>{#if fundDetailStatus==='loading'}<p class="micro-label">FUND DETAILS</p><h2>Loading fund details…</h2>{:else if fundDetailStatus==='error'}<p class="micro-label">FUND DETAILS</p><h2>Couldn’t load this fund</h2><p>{fundDetailError}</p><button class="primary" on:click={()=>openFundDetail(fundDetail.id)}>Try again</button>{:else}{@const detailSummary=fundSummary(fundDetail.id)}<p class="micro-label">FUND DETAILS</p><h2>{fundDetail.schemeName}</h2><div class="detail-value"><span>Current value</span><strong>{money(fundDetail.currentValue)}</strong></div><div class:positive={Number(fundDetail.profitOrLoss)>=0} class:negative={Number(fundDetail.profitOrLoss)<0} class="detail-pnl"><span>Total P&amp;L</span><strong>{Number(fundDetail.profitOrLoss)>=0?'+':''}{money(fundDetail.profitOrLoss)}</strong><b>{Number(fundDetail.profitOrLossPercent)>=0?'+':''}{Number(fundDetail.profitOrLossPercent).toFixed(2)}%</b></div><div class="detail-grid"><div><span>Invested</span><b>{money(fundDetail.invested)}</b></div><div><span>Units</span><b>{Number(fundDetail.units).toFixed(3)}</b></div><div><span>Average NAV</span><b>{moneyDecimal(fundDetail.averageNav)}</b></div><div><span>Current NAV</span><b>{moneyDecimal(fundDetail.currentNav)}</b></div></div>{#if fundDetail.history?.length}<section class="investment-history"><h3>Investment history</h3>{#each fundDetail.history as entry}<div class="investment-history-row"><span>{dateLabel(entry.transactionDate)}</span><strong>{entry.kind==="SIP"?"SIP":entry.kind==="LUMPSUM"?"Lump sum":"Opening holding"}</strong><span class="history-amount"><b>{money(entry.amount)}</b><button class="history-edit" on:click={()=>openHistoryEdit(detailSummary,entry)} aria-label="Edit this investment" title="Edit this investment">🔧</button></span><small>NAV {moneyDecimal(entry.nav)} · {Number(entry.units).toFixed(3)} units</small></div>{/each}</section>{/if}<p class="fund-disclaimer">Average NAV is based on confirmed investments. Current NAV is the latest available MFAPI value.</p>{/if}</section></div>{/if}
{#if lumpSumFund}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-form" role="dialog" aria-modal="true"><button class="close" on:click={()=>lumpSumFund=null}>×</button><p class="micro-label">LUMP-SUM INVESTMENT</p><h2>Add to {lumpSumFund.schemeName}</h2><p class="module-reassurance">This adds confirmed units to this fund only. It does not change the monthly SIP plan.</p><label>Amount invested<input type="number" min="0.01" step="0.01" bind:value={lumpSumForm.amount}/></label><label>Transaction date<input type="date" bind:value={lumpSumForm.transactionDate}/></label><label>NAV<input type="number" min="0.0001" step="0.0001" bind:value={lumpSumForm.nav} placeholder="e.g. 87.25"/></label>{#if lumpSumError}<p class="form-error">{lumpSumError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>lumpSumFund=null}>Cancel</button><button class="primary" on:click={saveLumpSum} disabled={lumpSumSaving}>{lumpSumSaving?'Adding…':'Add lump sum'}</button></div></section></div>{/if}
{#if confirmingSip}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-form" role="dialog" aria-modal="true"><button class="close" on:click={()=>confirmingSip=null}>×</button><p class="micro-label">CONFIRM SIP INVESTMENT</p><h2>Was this SIP processed?</h2><p class="module-reassurance">Units will be estimated from the NAV and marked as an estimate until you correct them from your statement.</p><div class="source-note"><strong>{confirmingSip.fund.schemeName}</strong><span>{confirmingSip.occurrence.scheduledMonth} occurrence</span></div><label>Amount invested<input type="number" min="0.01" step="0.01" bind:value={sipConfirmForm.amount}/></label><label>Transaction date<input type="date" bind:value={sipConfirmForm.transactionDate}/></label><label>NAV <span class="optional">Estimated</span><input type="number" min="0.0001" step="0.0001" bind:value={sipConfirmForm.nav} placeholder="e.g. 87.25"/></label>{#if sipConfirmError}<p class="form-error">{sipConfirmError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>confirmingSip=null}>Cancel</button><button class="primary" on:click={saveSipConfirmation} disabled={sipConfirmSaving}>{sipConfirmSaving?'Confirming…':'Confirm estimate'}</button></div></section></div>{/if}
{#if editingFundTransaction}<div class="modal-backdrop fund-form-backdrop"><section class="modal fund-form" role="dialog" aria-modal="true"><button class="close" on:click={()=>editingFundTransaction=null}>×</button><p class="micro-label">EDIT INVESTMENT</p><h2>{editingFundTransaction.entry.kind==="SIP"?"Edit SIP allocation":editingFundTransaction.entry.kind==="LUMPSUM"?"Edit lump sum":"Edit opening holding"}</h2><p class="module-reassurance">Update this recorded investment. Your fund totals will recalculate automatically.</p><label>Amount invested<input type="number" min="0.01" step="0.01" bind:value={fundTransactionForm.amount}/></label><label>Transaction date<input type="date" bind:value={fundTransactionForm.transactionDate}/></label><label>NAV<input type="number" min="0.0001" step="0.0001" bind:value={fundTransactionForm.nav}/></label>{#if fundTransactionError}<p class="form-error">{fundTransactionError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>editingFundTransaction=null}>Cancel</button><button class="primary" on:click={saveFundTransaction} disabled={fundTransactionSaving}>{fundTransactionSaving?"Saving…":"Save changes"}</button></div></section></div>{/if}
<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if showNormalization}<div class="account-repair-backdrop" role="presentation" on:click={()=>showNormalization=false} on:keydown={(event)=>event.key==='Escape'&&(showNormalization=false)}><section class="account-repair-dialog" role="dialog" aria-modal="true" tabindex="-1" on:click|stopPropagation><header class="account-repair-bar"><div><span class="repair-symbol">✦</span><span><p>EXPENSE DATA ONLY</p><strong>Expense cleanup</strong></span></div><button on:click={()=>showNormalization=false}>×</button></header><div class="account-repair-content"><Normalization /></div></section></div>{/if}
<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if openedStory}<div class="story-reader-backdrop" role="presentation" on:click={()=>openedStory=null} on:keydown={(event)=>event.key==='Escape'&&(openedStory=null)}><section class="story-detail" role="dialog" aria-modal="true" tabindex="-1" on:click|stopPropagation><button class="back-button" on:click={()=>openedStory=null}>← Back to stories</button><p class="micro-label">{storySource(openedStory).toUpperCase()} · {storyName(openedStory)}</p>{#if hasDeck}{@const cards=openedStory.cards.slice().sort((a,b)=>(a.sequence||0)-(b.sequence||0))}{@const currentCard=cards[storySlide]}<div class="story-deck">{#if cards.length>1}<div class="story-progress">{#each cards as _,index}<i class:active={index===storySlide}></i>{/each}</div>{/if}<article class={`story-slide deck-theme-${currentCard.theme||'CALM_CONTEXT'}`} on:touchstart={event=>(storyTouchStart=event.touches[0].clientX)} on:touchend={event=>endStorySwipe(event,cards.length)}>{#if currentCard.eyebrow}<p class="slide-eyebrow">{currentCard.eyebrow}</p>{/if}{#if currentCard.layout==='HERO_STAT'&&currentCard.components?.[0]}<div class="story-amount"><span>{currentCard.components[0].label}</span><strong>{currentCard.components[0].displayValue}</strong></div>{/if}<h1>{currentCard.title}</h1><p>{currentCard.body}</p>{#if currentCard.components?.length}<div class="observation-components">{#each currentCard.components as component}<div><span>{component.label}</span><strong>{component.displayValue}</strong></div>{/each}</div>{/if}{#each currentCard.actions||[] as action}{#if action.type==='OPEN_EVIDENCE'}<button class="story-action" data-testid="view-included-commitments" on:click={openCommitmentSources}>{action.label}</button>{:else if action.type==='OPEN_SALARY_OUTLOOK'}<button class="story-action" on:click={()=>{openedStory=null;openMoney();}}>{action.label}</button>{:else if action.type==='OPEN_DUE_LOAN'}<button class="story-action" data-testid="review-final-emi" on:click={openDueLoanFromStory}>{action.label}</button>{/if}{/each}</article>{#if cards.length>1}<div class="story-deck-controls"><button disabled={storySlide===0} on:click={()=>storySlide-=1}>←</button><span>{storySlide+1} of {cards.length}</span><button disabled={storySlide===cards.length-1} on:click={()=>storySlide+=1}>Next →</button></div>{/if}</div>{/if}</section></div>{/if}
<!-- svelte-ignore a11y_click_events_have_key_events -->
{#if showCommitmentReview}<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="close" on:click={()=>showCommitmentReview=false}>×</button><p class="micro-label">MONTHLY COMMITMENT</p><h2>Help match this payment</h2><p class="module-reassurance">Your expense was saved normally. Link it only if it belongs to one of your commitments.</p>{#if commitmentReviewStatus==='loading'}<p>Loading payment choices…</p>{:else if commitmentReviewStatus==='error'}<p class="form-error">{commitmentError}</p>{:else}{#each commitmentReview as candidate}<div class="source-note"><strong>{money(candidate.amount)} · {candidate.category} / {candidate.subcategory}</strong><span>{dateLabel(candidate.transactionDate)}</span></div><p>Which commitment is this for?</p>{#each candidate.choices as choice}<button class="story-action" on:click={()=>resolveCandidate(candidate.transactionId,choice.id)} disabled={resolvingCandidate===candidate.transactionId}>{choice.label}</button>{/each}<button class="secondary" on:click={()=>resolveCandidate(candidate.transactionId,null)} disabled={resolvingCandidate===candidate.transactionId}>This is not a commitment</button>{/each}{#if !commitmentReview.length}<p>Everything is reviewed for this month.</p>{/if}{/if}</section></div>{/if}
{#if showStoryEvidence}<div class="modal-backdrop" on:click={()=>showStoryEvidence=false} on:keydown={(event)=>event.key==='Escape'&&(showStoryEvidence=false)} role="presentation"><section class="modal" on:click|stopPropagation role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>showStoryEvidence=false}>×</button><p class="micro-label">INCLUDED COMMITMENTS</p><h2>{isCommitment(openedStory)?'What makes up this month':'Supporting evidence'}</h2>{#if evidenceItems.length}<p class="evidence-total">{evidenceItems.length} included {evidenceItems.length===1?'commitment':'commitments'}</p><div class="evidence-list">{#each evidenceItems as item}{@const loanItem=/loan/i.test(item.category)}{@const fundItem=item.sourceType==='mutual_fund_sip'}{@const stockItem=item.sourceType==='stock_monthly_plan'}{@const recurringItem=item.sourceType==='recurring_commitment'}{@const recurringStatus=recurringOccurrence(item.sourceId)?.status}<div class:due-commitment={(loanItem&&currentCommitmentIsDue())||(fundItem&&sipIsDue(item))||(stockItem&&stocks.find(stock=>String(stock.id)===String(item.sourceId))?.currentMonthlyPlan?.status==='DUE')||(recurringItem&&recurringStatus==='DUE')} class:confirmed-commitment={(fundItem&&sipIsConfirmed(item))||(recurringItem&&recurringStatus==='COMPLETED')} class="evidence-row"><div><strong>{item.merchant}</strong><span>{item.date}{item.date&&item.category?' · ':''}{item.category}</span></div><b>{item.amount}</b>{#if loanItem}<button class="secondary" data-testid="included-loan-commitment" on:click={openIncludedLoan}>Review</button>{:else if fundItem}<button class="secondary" data-testid={`included-mutual-fund-commitment-${item.sourceId}`} on:click={()=>openIncludedMutualFund(item)}>Review</button>{:else if stockItem}<button class="secondary" data-testid={`included-stock-commitment-${item.sourceId}`} on:click={()=>openIncludedStock(item)}>Review</button>{:else if recurringItem}<button class="secondary" data-testid={`included-recurring-commitment-${item.sourceId}`} on:click={()=>openIncludedCommitment(item)}>Review</button>{/if}</div>{/each}</div>{:else}<div class="empty-state evidence-empty"><span>◌</span><h2>No commitments attached</h2><p>This story does not include sources to display.</p></div>{/if}</section></div>{/if}
{#if editing}<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>editing=null}>×</button><p class="micro-label">AI-CAPTURED EXPENSE</p><h2>Edit transaction</h2><div class="source-note"><strong>Captured from your message</strong><span>Review the details below before saving.</span></div><label>Amount<input type="number" inputmode="decimal" min="0.01" step="0.01" bind:value={editAmount}/></label><label>Transaction date<input type="date" max={new Date().toISOString().slice(0,10)} bind:value={editDate}/></label>{#if optionsStatus==='loading'}<p class="edit-options-status">Loading categories, merchants, and accounts…</p>{:else if optionsStatus==='error'}<p class="form-error">{optionsError}</p>{:else}<label>Category<select value={editCategory} on:change={changeEditCategory}><option value="" disabled>Select a category</option>{#each editOptions.categories as option}<option value={option.name}>{option.name}</option>{/each}</select></label><label>Subcategory<select bind:value={editSubcategory} disabled={!editCategory}><option value="" disabled>Select a subcategory</option>{#each editSubcategories as option}<option value={option}>{option}</option>{/each}</select></label><label>Merchant<select bind:value={editMerchantId}><option value="" disabled>Select a merchant</option>{#each editOptions.merchants as option}<option value={String(option.id)}>{option.name}</option>{/each}</select></label><label>Source account<select bind:value={editAccountId}><option value="" disabled>Select an account</option>{#each editOptions.accounts as option}<option value={String(option.id)}>{option.name}</option>{/each}</select></label>{/if}{#if actionError}<p class="form-error">{actionError}</p>{/if}<div class="modal-actions"><button class="secondary" on:click={()=>editing=null}>Cancel</button><button class="primary" on:click={saveEdit} disabled={saving||optionsStatus!=='ready'}>{saving?'Saving…':'Save changes'}</button></div></section></div>{/if}
{#if deleting}<div class="modal-backdrop"><section class="modal" role="alertdialog" aria-modal="true" tabindex="-1"><p class="micro-label">DELETE TRANSACTION</p><h2>Delete {merchant(deleting)}?</h2><p>This updates the calendar and monthly totals.</p><div class="modal-actions"><button class="secondary" on:click={()=>deleting=null}>Cancel</button><button class="primary delete-confirm" on:click={confirmDelete}>Delete</button></div></section></div>{/if}
{#if handoff}<div class="modal-backdrop"><section class="modal whatsapp-handoff" role="dialog" aria-modal="true" tabindex="-1"><button class="close" on:click={()=>handoff=null}>×</button><p class="micro-label">WHATSAPP READY</p><h2>Continue in WhatsApp</h2><p>Send the missing transaction for {dateLabel(`${handoff.date}T12:00:00`)}.</p>{#if handoff.whatsappUrl}<a class="center-action whatsapp-action" href={handoff.whatsappUrl} target="_blank" rel="noopener">Open WhatsApp</a>{/if}<button class="auth-secondary" on:click={()=>handoff=null}>Done</button></section></div>{/if}
